<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="<?=app_url()?>">Ana Sayfa</a><span>›</span><span>Arama</span></div><h1><?=$q!==''?'“'.h($q).'” için sonuçlar':'Tüm Ürünler'?></h1><p><?=count($products)?> ürün bulundu</p></div></section>
